package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

var drivers = map[string]bool{}

func register(name string) error {
	if drivers[name] {
		return fmt.Errorf("sql: Register called twice for driver %s", name)
	}
	drivers[name] = true
	return nil
}

func open(name string) error {
	if !drivers[name] {
		return fmt.Errorf("sql: unknown driver %q (forgotten import?)", name)
	}
	return nil
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) != 2 {
			continue
		}
		var err error
		switch f[0] {
		case "register":
			if err = register(f[1]); err == nil {
				fmt.Println("registered", f[1])
			}
		case "open":
			if err = open(f[1]); err == nil {
				fmt.Println("ok", f[1])
			}
		default:
			continue
		}
		if err != nil {
			fmt.Println("error:", err)
		}
	}
}
